if (isNaN(v)) { return '<span style="color: var(--tb-ai-text-secondary, #757575)">–</span>'; }
const text = v.toFixed(1) + " °C";
let min = 0, max = 100, upper = NaN, lower = NaN;
min = 0.0;
max = 50.0;
upper = parseFloat(entity["Temp High"]);
const pct = Math.min(100, Math.max(0, (v - min) / (max - min) * 100));
const near = (max - min) * 0.05;
let color = 'var(--tb-ai-primary, #00695C)';
if (!isNaN(upper)) { color = v > upper ? '#EF4444' : v > upper - near ? '#F59E0B' : '#10B981'; }
if (!isNaN(lower)) { color = v < lower ? '#EF4444' : v < lower + near ? '#F59E0B' : '#10B981'; }
return '<div style="display: flex; align-items: center; gap: 12px; min-width: 160px;">'
