}

.farm-page__theme-btn {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.2s;
}

.farm-page__theme-btn:hover {
  background: color-mix(in srgb,var(--primary) 8%,transparent);
}

.kpi-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(210px,1fr));
  gap: 16px;
}

.kpi-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 16px;
  background: var(--surface);
  border: var(--tb-ai-card-border);
  border-radius: var(--tb-ai-card-radius);
  box-shadow: var(--tb-ai-card-shadow);
}

.kpi-card--alert {
  border-color: color-mix(in srgb,#D32F2F 40%,transparent);
}

.kpi-card__top {
  display: flex;
  align-items: center;
  gap: 10px;
  position: relative;
}

.kpi-card__icon {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  flex: none;
}

.kpi-card__icon tb-icon {
  font-size: 18px;
}

.kpi-card__icon--temp {
  background: #ED6C02;
}

.kpi-card__icon--gas {
  background: var(--primary);
}

.kpi-card__icon--coops {
  background: #2E7D32;
}

.kpi-card__icon--alarm {
  background: #D32F2F;
}

.kpi-card__title {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  flex: 1;
}

.kpi-card__value {
  margin-top: 4px;
  font-size: 26px;
  font-weight: 700;
  line-height: 1.1;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.kpi-card__value small {
  margin-left: 3px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
}

.kpi-card__value--crit {
  color: #D32F2F;
}

.kpi-card__caption {
  font-size: 12px;
  color: var(--text-secondary);
}

.kpi-card__track {
  height: 6px;
  margin-top: auto;
  border-radius: 3px;
  background: color-mix(in srgb,var(--text) 10%,transparent);
  overflow: hidden;
}

.kpi-card__fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--primary);
  transition: width 0.4s ease;
}

.kpi-card__fill--crit {
  background: #D32F2F;
}

.tile__history {
  flex: none;
  margin-left: auto;
  width: 28px;
  height: 28px;
  border: 1px solid color-mix(in srgb,var(--primary) 28%,transparent);
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--primary);
  background: color-mix(in srgb,var(--primary) 12%,transparent);
  box-shadow: 0 1px 2px rgba(0,0,0,0.18),inset 0 1px 0 color-mix(in srgb,var(--surface,#FFFFFF) 70%,transparent);
  transition: background 0.15s,box-shadow 0.15s;
}

.tile__history:hover {
  background: color-mix(in srgb,var(--primary) 20%,transparent);
  box-shadow: 0 2px 5px rgba(0,0,0,0.22);
}

.tile__history tb-icon {
  font-size: 18px;
}

.farm-page__body {
  display: flex;
  flex-direction: column;
  gap: 16px;
  flex: 1;
}

.farm-page__split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.farm-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.farm-section__head {
  display: flex;
  align-items: center;
  gap: 8px;
}

.farm-section__title {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-secondary);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.farm-section__title tb-icon {
  font-size: 16px;
  color: var(--primary);
}

.farm-section__embed {
  width: 100%;
  border-radius: var(--tb-ai-card-radius);
  overflow: hidden;
}

.farm-section__embed tb-dashboard-state {
  display: block;
  width: 100%;
  height: 100%;
}

.farm-section__embed--map {
  height: 460px;
}

.farm-section__embed--alarms {
  height: 460px;
}

.farm-section__embed--coops {
  height: 420px;
}

@container farmpage (max-width:960px) {
  .farm-page__split {
    grid-template-columns: 1fr;
  }
  .farm-section__embed--map {
    height: 380px;
  }
  .farm-section__embed--alarms {
    height: 380px;
  }
}

/* tb-ai-toggle-pinned */
.farm-page__header { flex-wrap: wrap; align-items: flex-start; }
.farm-page__header > * { min-width: 0; flex: 1 1 240px; }
.farm-page__header > .farm-page__header-actions { flex: none; width: auto; max-width: 100%; margin-left: auto; }
.farm-page__header { position: relative; padding-right: calc(20px + 48px); }
.farm-page__header :has([data-tb-ai-theme-toggle]) { position: static; }
.farm-page__header [data-tb-ai-theme-toggle] { position: absolute; top: 16px; right: 20px; margin: 0; z-index: 1; }

/* tb-ai-history-buttons */
button.tile__history.tile__history { border: 1px solid color-mix(in srgb, var(--tb-ai-primary, var(--tb-primary-500)) 28%, transparent); border-radius: 8px; background: color-mix(in srgb, var(--tb-ai-primary, var(--tb-primary-500)) 12%, transparent); color: var(--tb-ai-primary, var(--tb-primary-500)); cursor: pointer; box-shadow: 0 1px 2px rgba(0,0,0,0.18), inset 0 1px 0 color-mix(in srgb, var(--tb-ai-surface, #FFFFFF) 70%, transparent); transition: background 0.15s, box-shadow 0.15s; }
button.tile__history.tile__history:hover { background: color-mix(in srgb, var(--tb-ai-primary, var(--tb-primary-500)) 20%, transparent); box-shadow: 0 2px 5px rgba(0,0,0,0.22), inset 0 1px 0 color-mix(in srgb, var(--tb-ai-surface, #FFFFFF) 70%, transparent); }
button.tile__history.tile__history:active { box-shadow: inset 0 1px 3px rgba(0,0,0,0.25); }

/* tb-ai-fill */
.farm-page__body { flex: 1 0 auto; display: flex; flex-direction: column; }
.farm-section { flex: 1 0 auto; display: flex; flex-direction: column; }
.farm-section__embed--coops { flex: 1 0 auto; height: auto; min-height: 420px; }

/* tb-ai-responsive */
@media (max-width: 1279px) {
  .farm-section__embed--coops:has(> tb-dashboard-state[stateid="coops-overview"]) { height: 1050px; min-height: 1050px; }
}
@media (max-width: 959px) {
  .farm-section__embed--map:has(> tb-dashboard-state[stateid="farm-location-view"]) { height: 570px; min-height: 570px; }
  .farm-section__embed--alarms:has(> tb-dashboard-state[stateid="farm-alarms"]) { height: 570px; min-height: 570px; }
}

