this.coopsCount = null;
this.criticalAlarms = 0;
this.tempPercent = 0;
this.ammoniaPercent = 0;

this.openHistory = (event, stateId) => {
  event.stopPropagation();
  ctx.actionsApi.openDashboardStateInPopover(event, stateId, ctx.stateController.getStateParams(), true, 'bottom', true, '560px', '360px');
};

let farmSubId = null;
let coopsSubId = null;
let alarmSubId = null;

ctx.subscriptionApi.createSubscription({
  type: 'latest',
  datasources: [{
    type: 'entity',
    entityAliasId: ctx.aliasController.getEntityAliasId('Poultry Farm'),
    dataKeys: [
      { type: 'attribute', name: 'address', settings: {} },
      { type: 'timeseries', name: 'avgFarmTemperature', settings: {} },
      { type: 'timeseries', name: 'avgFarmAmmonia', settings: {} }
    ]
  }],
  callbacks: {
    onDataUpdated: (sub) => {
      for (const e of sub.data || []) {
        this.farmName = e.datasource.entityName;
        const last = e.data && e.data.length ? e.data[e.data.length - 1][1] : null;
        if (e.dataKey.name === 'address') {
          this.farmAddress = last || '';
        } else if (e.dataKey.name === 'avgFarmTemperature') {
          this.avgTemp = last !== null ? Number(last) : null;
          this.tempPercent = this.avgTemp !== null ? Math.min(100, Math.max(0, (this.avgTemp / 50) * 100)) : 0;
        } else if (e.dataKey.name === 'avgFarmAmmonia') {
          this.avgAmmonia = last !== null ? Number(last) : null;
          this.ammoniaPercent = this.avgAmmonia !== null ? Math.min(100, Math.max(0, (this.avgAmmonia / 100) * 100)) : 0;
