});

ctx.registerDestroyCallback(() => {
  if (farmSubId) ctx.subscriptionApi.removeSubscription(farmSubId);
  if (coopsSubId) ctx.subscriptionApi.removeSubscription(coopsSubId);
  if (alarmSubId) ctx.subscriptionApi.removeSubscription(alarmSubId);
});

settings.css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400%3B500%3B600%3B700&display=swap');

/* tb-ai-palette */ .page { --canvas: var(--tb-ai-canvas, #F7F8FA); --surface: var(--tb-ai-surface, #FFFFFF); --text: var(--tb-ai-text, rgba(0,0,0,0.87)); --text-secondary: var(--tb-ai-text-secondary, rgba(0,0,0,0.54)); --border: var(--tb-ai-border, rgba(0,0,0,0.12)); --primary: var(--tb-ai-primary, var(--tb-primary-500, #00695C)); --on-primary: var(--tb-ai-on-primary, var(--tb-primary-contrast-500, #FFFFFF)); --accent: var(--tb-ai-accent, var(--tb-accent-500, #FF5722)); }

tb-icon {
  width: 1em;
  height: 1em;
  min-width: 1em;
  min-height: 1em;
  font-size: 24px;
  line-height: 1;
}

.page {
  --tb-ai-font: 'Inter',sans-serif;
  font-family: var(--tb-ai-font);
  --tb-ai-card-border: 1px solid var(--border);
  --tb-ai-card-radius: 12px;
  --tb-ai-card-shadow: 0 1px 3px rgba(0,0,0,0.05);
  --tb-ai-card-padding: 16px;
  --tb-ai-card-title-size: 14px;
  --tb-ai-card-title-weight: 600;
  --tb-ai-card-title-color: var(--text);
  --tb-ai-card-title-line-height: 20px;
  --tb-ai-table-header-size: 12px;
  --tb-ai-table-header-weight: 600;
  --tb-ai-table-header-color: var(--text-secondary);
  --tb-ai-table-cell-size: 13px;
  --tb-ai-table-cell-weight: 400;
  --tb-ai-table-cell-color: var(--text);
  --tb-ai-table-divider-color: var(--border);
  height: 100%;
  box-sizing: border-box;
  overflow-y: auto;
  background: var(--canvas);
  color: var(--text);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.page__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding: 12px 16px;
  background: var(--surface);
  border: var(--tb-ai-card-border);
  border-radius: var(--tb-ai-card-radius);
  box-shadow: var(--tb-ai-card-shadow);
}

.page__title-area {
  display: flex;
  align-items: center;
  gap: 12px;
}

.page__back-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s,color 0.15s; white-space: nowrap; flex: none;
}

.page__back-btn:hover {
  background: color-mix(in srgb,var(--primary) 10%,transparent);
  color: var(--primary);
}

.page__titles {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.page__name-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.page__name {
  font-size: 18px;
  font-weight: 700;
  color: var(--text);
}

.page__updated {
  font-size: 12px;
  color: var(--text-secondary);
}

.page__header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.theme-toggle-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  cursor: pointer; white-space: nowrap; flex: none;
}

.theme-toggle-btn:hover {
  background: color-mix(in srgb,var(--text) 5%,transparent);
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  background: color-mix(in srgb,var(--text) 8%,transparent);
  color: var(--text-secondary); white-space: nowrap; flex: none;
}

.chip--ok {
  background: color-mix(in srgb,#2E7D32 15%,transparent);
  color: #2E7D32;
}

.chip--off {
  background: color-mix(in srgb,var(--text-secondary) 15%,transparent);
  color: var(--text-secondary);
}

.chip--crit {
  background: color-mix(in srgb,#D32F2F 15%,transparent);
  color: #D32F2F;
}

.chip--fan {
  background: color-mix(in srgb,var(--text) 8%,transparent);
  color: var(--text-secondary);
}

.chip--fan-on {
  background: color-mix(in srgb,var(--primary) 15%,transparent);
  color: var(--primary);
}

.page__kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(240px,1fr));
  gap: 16px;
}

.gtile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 16px;
  background: var(--surface);
  border: var(--tb-ai-card-border);
  border-radius: var(--tb-ai-card-radius);
  box-shadow: var(--tb-ai-card-shadow);
}

.gtile__top {
  align-self: stretch;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.gtile__title-group {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.gtile__icon {
  font-size: 18px;
  color: var(--text-secondary);
}

.gtile__title {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.gtile__actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.gtile__badge {
  flex: none;
  white-space: nowrap;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  color: var(--gauge-color,var(--text-secondary));
  background: color-mix(in srgb,currentColor 15%,transparent);
}

.gtile__badge--ok {
  color: #2E7D32;
}

.gtile__badge--warn {
  color: #ED6C02;
}

.gtile__badge--crit {
  color: #D32F2F;
}

.gtile__badge--none {
  color: var(--text-secondary);
}

.gtile__caption {
  font-size: 12px;
  color: var(--text-secondary);
}

.gtile__caption--crit {
  color: #D32F2F;
  font-weight: 500;
}

.tile__history {
  flex: none;
  width: 28px;
  height: 28px;
  border: 1px solid color-mix(in srgb,var(--primary) 28%,transparent);
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--primary);
  background: color-mix(in srgb,var(--primary) 12%,transparent);
  box-shadow: 0 1px 2px rgba(0,0,0,0.18);
  transition: background 0.15s,box-shadow 0.15s;
}

.tile__history:hover {
  background: color-mix(in srgb,var(--primary) 20%,transparent);
  box-shadow: 0 2px 5px rgba(0,0,0,0.22);
}

.tile__history tb-icon {
  font-size: 16px;
}

.gauge {
  --gauge-color: var(--primary);
  position: relative;
  width: 132px;
  aspect-ratio: 1;
  flex: none;
}

.gauge--ok {
  --gauge-color: #2E7D32;
}

.gauge--warn {
  --gauge-color: #ED6C02;
}

.gauge--crit {
  --gauge-color: #D32F2F;
}

.gauge--none {
  --gauge-color: var(--text-secondary);
}

.gauge__svg {
  width: 100%;
  height: 100%;
  display: block;
}

.gauge__track,.gauge__fill {
  fill: none;
  stroke-width: 10;
  stroke-linecap: round;
}

.gauge__track {
  stroke: color-mix(in srgb,var(--text) 10%,transparent);
}

.gauge__fill {
  stroke: var(--gauge-color);
  transition: stroke-dasharray 0.6s ease,stroke 0.3s ease;
}

.gauge__tick {
  stroke: var(--text);
  stroke-width: 3;
  stroke-linecap: round;
}

.gauge__center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.gauge__value {
  font-size: 26px;
  font-weight: 700;
  line-height: 1;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.gauge__unit {
  margin-top: 4px;
  font-size: 12px;
  color: var(--text-secondary);
}

.page__embed-controls {
  height: 980px;
  min-height: 200px;
}

.page__embed-controls tb-dashboard-state {
  display: block;
  width: 100%;
  height: 100%;
}

.page__section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 8px;
}

.page__section-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
}

.page__section-title tb-icon {
  color: var(--primary);
}

.page__time-range {
  display: flex;
  align-items: center;
}

.page__embed-history {
  height: 650px;
  min-height: 420px;
}

.page__embed-history tb-dashboard-state {
  display: block;
  width: 100%;
  height: 100%;
}

.page__embed-alarms {
  height: 340px;
  min-height: 340px;
}

.page__embed-alarms tb-dashboard-state {
  display: block;
  width: 100%;
  height: 100%;
}

/* tb-ai-toggle-pinned */
.page__header { flex-wrap: wrap; align-items: flex-start; }
.page__header > * { min-width: 0; flex: 1 1 240px; }
.page__header > .page__header-actions { flex: none; width: auto; max-width: 100%; margin-left: auto; }
.page__header { position: relative; padding-right: calc(16px + 48px); }
.page__header :has([data-tb-ai-theme-toggle]) { position: static; }
.page__header [data-tb-ai-theme-toggle] { position: absolute; top: 12px; right: 16px; margin: 0; z-index: 1; }

/* tb-ai-history-buttons */
button.tile__history.tile__history { border: 1px solid color-mix(in srgb, var(--tb-ai-primary, var(--tb-primary-500)) 28%, transparent); border-radius: 8px; background: color-mix(in srgb, var(--tb-ai-primary, var(--tb-primary-500)) 12%, transparent); color: var(--tb-ai-primary, var(--tb-primary-500)); cursor: pointer; box-shadow: 0 1px 2px rgba(0,0,0,0.18), inset 0 1px 0 color-mix(in srgb, var(--tb-ai-surface, #FFFFFF) 70%, transparent); transition: background 0.15s, box-shadow 0.15s; }
button.tile__history.tile__history:hover { background: color-mix(in srgb, var(--tb-ai-primary, var(--tb-primary-500)) 20%, transparent); box-shadow: 0 2px 5px rgba(0,0,0,0.22), inset 0 1px 0 color-mix(in srgb, var(--tb-ai-surface, #FFFFFF) 70%, transparent); }
button.tile__history.tile__history:active { box-shadow: inset 0 1px 3px rgba(0,0,0,0.25); }

/* tb-ai-fill */
.page__embed-alarms { flex: 1 0 auto; height: auto; min-height: 340px; }

/* tb-ai-responsive */
