const ARC = 'M26.06 93.94 A48 48 0 1 1 93.94 93.94';
this.arc = ARC;

const arcPoint = (frac, r) => {
  const a = (135 + 270 * frac) * Math.PI / 180;
  return { x: (60 + r * Math.cos(a)).toFixed(2), y: (60 + r * Math.sin(a)).toFixed(2) };
};

const gauge = (value, min, max, limits) => {
  const clamp = (v) => Math.min(1, Math.max(0, (v - min) / (max - min)));
  const ticks = limits.map((limit) => {
    const inner = arcPoint(clamp(limit), 40), outer = arcPoint(clamp(limit), 56);
    return { x1: inner.x, y1: inner.y, x2: outer.x, y2: outer.y };
  });
  const known = value !== null && value !== undefined && !isNaN(value);
  return { dash: (known ? clamp(value) * 100 : 0).toFixed(1) + ' 100', ticks, known };
};

const ago = (ts) => {
  if (!ts) return '';
  const m = Math.round((Date.now() - ts) / 60000);
  return m < 1 ? 'just now' : m < 60 ? m + ' min ago' : m < 1440 ? Math.round(m / 60) + ' h ago' : Math.round(m / 1440) + ' d ago';
};

this.temp = { text: '—', status: 'No data', tone: 'none', limitText: '', g: { dash: '0 100', ticks: [] } };
this.hum = { text: '—', status: 'No data', tone: 'none', limitText: '', g: { dash: '0 100', ticks: [] } };
this.nh3 = { text: '—', status: 'No data', tone: 'none', limitText: '', g: { dash: '0 100', ticks: [] } };
this.noiseData = { text: '—', status: 'No data', tone: 'none', limitText: '', g: { dash: '0 100', ticks: [] } };

this.goBack = () => {
  ctx.stateController.navigatePrevState(Math.max(ctx.stateController.getStateIndex() - 1, 0));
};

this.openHistory = (event, stateId) => {
  event.stopPropagation();
  ctx.actionsApi.openDashboardStateInPopover(event, stateId, ctx.stateController.getStateParams(), true, 'bottom', true, '560px', '360px');
};

let subId = null;
ctx.subscriptionApi.createSubscription({
  type: 'latest',
  datasources: [{
    type: 'entity',
    entityAliasId: ctx.aliasController.getEntityAliasId('Selected Coop Controller'),
    dataKeys: [
      { type: 'attribute', name: 'active', settings: {} },
      { type: 'attribute', name: 'tempHighThreshold', settings: {} },
      { type: 'attribute', name: 'tempLowThreshold', settings: {} },
      { type: 'attribute', name: 'humidityHighThreshold', settings: {} },
      { type: 'attribute', name: 'ammoniaThreshold', settings: {} },
      { type: 'attribute', name: 'noiseThreshold', settings: {} },
      { type: 'timeseries', name: 'temperature', settings: {} },
      { type: 'timeseries', name: 'humidity', settings: {} },
      { type: 'timeseries', name: 'ammonia', settings: {} },
      { type: 'timeseries', name: 'noise', settings: {} },
      { type: 'timeseries', name: 'fanStatus', settings: {} },
      { type: 'timeseries', name: 'sensorFault', settings: {} }
    ]
  }],
  callbacks: {
    onDataUpdated: (sub) => {
      const v = {};
      let maxT = 0;
      for (const e of sub.data || []) {
        if (e.datasource && e.datasource.entityName) {
          this.name = e.datasource.entityName;
        }
        if (e.data && e.data.length) {
          const pair = e.data[e.data.length - 1];
          v[e.dataKey.name] = pair[1];
          if (pair[0] > maxT) maxT = pair[0];
        } else {
          v[e.dataKey.name] = null;
        }
      }
      if (maxT > 0) {
        lastTs = maxT;
        this.lastUpdated = ago(lastTs);
        this.lastUpdatedFull = new Date(lastTs).toLocaleString();
      }

      this.activeKnown = v.active !== null && v.active !== undefined;
      this.online = v.active === true || v.active === 'true';
      this.fanStatus = v.fanStatus !== null && v.fanStatus !== undefined ? (v.fanStatus === true || v.fanStatus === 'true') : null;
      this.sensorFault = v.sensorFault === true || v.sensorFault === 'true';

      const tVal = v.temperature !== null ? Number(v.temperature) : null;
      const tHigh = v.tempHighThreshold !== null ? Number(v.tempHighThreshold) : null;
      const tLow = v.tempLowThreshold !== null ? Number(v.tempLowThreshold) : null;
      const tLimits = [tLow, tHigh].filter((x) => x !== null && !isNaN(x));
      let tTone = 'none';
      let tStatus = 'No data';
      if (tVal !== null && !isNaN(tVal)) {
        if ((tHigh !== null && tVal > tHigh) || (tLow !== null && tVal < tLow)) {
          tTone = 'crit';
          tStatus = tVal > tHigh ? 'High' : 'Low';
        } else {
          tTone = 'ok';
          tStatus = 'Normal';
        }
      }
      this.temp = {
        text: tVal !== null && !isNaN(tVal) ? tVal.toFixed(1) : '—',
        status: tStatus,
        tone: tTone,
        limitText: tHigh !== null ? 'High Limit: ' + tHigh.toFixed(1) + ' °C' : '',
        g: gauge(tVal, 0, 50, tLimits)
      };

      const hVal = v.humidity !== null ? Number(v.humidity) : null;
      const hHigh = v.humidityHighThreshold !== null ? Number(v.humidityHighThreshold) : null;
      const hLimits = hHigh !== null && !isNaN(hHigh) ? [hHigh] : [];
      let hTone = 'none';
      let hStatus = 'No data';
      if (hVal !== null && !isNaN(hVal)) {
        if (hHigh !== null && hVal > hHigh) {
          hTone = 'crit';
          hStatus = 'High';
        } else {
          hTone = 'ok';
          hStatus = 'Normal';
        }
      }
      this.hum = {
        text: hVal !== null && !isNaN(hVal) ? hVal.toFixed(1) : '—',
        status: hStatus,
        tone: hTone,
        limitText: hHigh !== null ? 'High Limit: ' + hHigh.toFixed(0) + ' %' : '',
        g: gauge(hVal, 0, 100, hLimits)
      };

      const nh3Val = v.ammonia !== null ? Number(v.ammonia) : null;
      const nh3High = v.ammoniaThreshold !== null ? Number(v.ammoniaThreshold) : null;
      const nh3Limits = nh3High !== null && !isNaN(nh3High) ? [nh3High] : [];
      let nh3Tone = 'none';
      let nh3Status = 'No data';
      if (nh3Val !== null && !isNaN(nh3Val)) {
        if (nh3High !== null && nh3Val > nh3High) {
          nh3Tone = 'crit';
          nh3Status = 'High';
        } else {
          nh3Tone = 'ok';
          nh3Status = 'Normal';
        }
      }
      this.nh3 = {
        text: nh3Val !== null && !isNaN(nh3Val) ? nh3Val.toFixed(1) : '—',
        status: nh3Status,
        tone: nh3Tone,
        limitText: nh3High !== null ? 'Threshold: ' + nh3High.toFixed(1) + ' ppm' : '',
        g: gauge(nh3Val, 0, 100, nh3Limits)
      };

      const nVal = v.noise !== null ? Number(v.noise) : null;
      const nHigh = v.noiseThreshold !== null ? Number(v.noiseThreshold) : null;
      const nLimits = nHigh !== null && !isNaN(nHigh) ? [nHigh] : [];
      let nTone = 'none';
      let nStatus = 'No data';
      if (nVal !== null && !isNaN(nVal)) {
        if (nHigh !== null && nVal > nHigh) {
          nTone = 'crit';
          nStatus = 'Loud';
        } else {
          nTone = 'ok';
          nStatus = 'Normal';
        }
      }
      this.noiseData = {
        text: nVal !== null && !isNaN(nVal) ? nVal.toFixed(1) : '—',
        status: nStatus,
        tone: nTone,
        limitText: nHigh !== null ? 'Threshold: ' + nHigh.toFixed(0) + ' dB' : '',
        g: gauge(nVal, 0, 120, nLimits)
      };

      ctx.detectChanges();
    }
  }
}, true).subscribe((sub) => { subId = sub.id; });

const timer = setInterval(() => {
  if (lastTs > 0) {
    this.lastUpdated = ago(lastTs);
    ctx.detectChanges();
  }
}, 60000);

ctx.registerDestroyCallback(() => {
  if (subId) ctx.subscriptionApi.removeSubscription(subId);
  clearInterval(timer);
});

