@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400%3B500%3B600%3B700&display=swap');

/* tb-ai-palette */ .coop-page { --canvas: var(--tb-ai-canvas, #F7F8FA); --surface: var(--tb-ai-surface, #FFFFFF); --text: var(--tb-ai-text, rgba(0,0,0,0.87)); --text-secondary: var(--tb-ai-text-secondary, rgba(0,0,0,0.54)); --border: var(--tb-ai-border, rgba(0,0,0,0.12)); --primary: var(--tb-ai-primary, var(--tb-primary-500, #00695C)); --on-primary: var(--tb-ai-on-primary, var(--tb-primary-contrast-500, #FFFFFF)); --accent: var(--tb-ai-accent, var(--tb-accent-500, #FF5722)); }

tb-icon {
  width: 1em;
  height: 1em;
  min-width: 1em;
  min-height: 1em;
  font-size: 24px;
  line-height: 1;
}

.coop-page {
  --tb-ai-font: 'Inter',sans-serif;
  font-family: var(--tb-ai-font);
  --tb-ai-card-border: 1px solid var(--border);
  --tb-ai-card-radius: 12px;
  --tb-ai-card-shadow: 0 1px 3px rgba(0,0,0,0.06);
  --tb-ai-card-padding: 16px;
  --tb-ai-card-title-size: 12px;
  --tb-ai-card-title-weight: 600;
  --tb-ai-card-title-color: var(--text-secondary);
  --tb-ai-card-title-line-height: 16px;
  --tb-ai-table-header-size: 12px;
  --tb-ai-table-header-weight: 600;
  --tb-ai-table-header-color: var(--text-secondary);
  --tb-ai-table-cell-size: 13px;
  --tb-ai-table-cell-weight: 400;
  --tb-ai-table-cell-color: var(--text);
  --tb-ai-table-divider-color: var(--border);
  height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
  background: var(--canvas);
  color: var(--text);
  overflow-y: auto;
}

.coop-page__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--surface);
  border: var(--tb-ai-card-border);
  border-radius: var(--tb-ai-card-radius);
  box-shadow: var(--tb-ai-card-shadow);
  flex-wrap: wrap;
  gap: 12px;
}

.head__left {
  display: flex;
  align-items: center;
  gap: 14px;
}

.btn-back {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.2s,border-color 0.2s; white-space: nowrap; flex: none;
}

.btn-back:hover {
  background: color-mix(in srgb,var(--primary) 10%,transparent);
  border-color: var(--primary);
}

.head__titles {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.head__badge {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--primary);
}

.head__name {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  color: var(--text);
}

.head__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.freshness {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-secondary);
}

.freshness tb-icon {
  font-size: 16px;
}

.theme-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer; white-space: nowrap; flex: none;
}

.theme-btn tb-icon {
  font-size: 18px;
}

.coop-page__kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(220px,1fr));
  gap: 12px;
}

.kpi-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  background: var(--surface);
  border: var(--tb-ai-card-border);
  border-radius: var(--tb-ai-card-radius);
  box-shadow: var(--tb-ai-card-shadow);
}

.kpi-card__top {
  display: flex;
  align-items: center;
  gap: 10px;
}

.kpi-card__icon {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
}

.kpi-card__icon tb-icon {
  font-size: 18px;
}

.kpi-card__icon--temp {
  background: #ED6C02;
}

.kpi-card__icon--ammonia {
  background: #7B1FA2;
}

.kpi-card__icon--fans {
  background: #2E7D32;
}

.kpi-card__title {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  flex: 1;
  min-width: 0;
}

.kpi-card__value {
  font-size: 28px;
  font-weight: 700;
  color: var(--text);
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
}

.kpi-card__value small {
  margin-left: 4px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
}

.kpi-card__caption {
  font-size: 12px;
  color: var(--text-secondary);
}

.kpi-card__track {
  height: 6px;
  border-radius: 3px;
  background: color-mix(in srgb,var(--text) 10%,transparent);
  overflow: hidden;
  margin-top: auto;
}

.kpi-card__track i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--primary);
  transition: width 0.6s ease;
}

.tile__history {
  flex: none;
  margin-left: auto;
  width: 28px;
  height: 28px;
  border: 1px solid color-mix(in srgb,var(--primary) 28%,transparent);
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--primary);
  background: color-mix(in srgb,var(--primary) 12%,transparent);
  box-shadow: 0 1px 2px rgba(0,0,0,0.18),inset 0 1px 0 color-mix(in srgb,var(--surface) 70%,transparent);
  transition: background 0.15s,box-shadow 0.15s;
}

.tile__history:hover {
  background: color-mix(in srgb,var(--primary) 20%,transparent);
  box-shadow: 0 2px 5px rgba(0,0,0,0.22),inset 0 1px 0 color-mix(in srgb,var(--surface) 70%,transparent);
}

.tile__history tb-icon {
  font-size: 18px;
}

.coop-page__tabs {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  white-space: nowrap;
  flex: none;
  max-width: 100%;
  min-width: 0;
  padding-bottom: 2px; overflow-y: hidden;
}

.tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.tab-btn tb-icon {
  font-size: 18px;
}

.tab-btn:hover {
  color: var(--text);
  border-color: color-mix(in srgb,var(--primary) 30%,transparent);
}

.tab-btn.is-active {
  color: var(--primary);
  background: color-mix(in srgb,var(--primary) 12%,transparent);
  border-color: var(--primary);
}

.alarm-counter {
  background: #D32F2F;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  padding: 1px 7px;
  border-radius: 999px; white-space: nowrap; flex: none;
}

.coop-page__view {
  flex: 1;
  min-height: 480px;
  display: flex;
  flex-direction: column;
}

.embed-wrapper {
  flex: 1;
  height: 100%;
  min-height: 480px;
  height: 480px;
}

.embed-wrapper tb-dashboard-state {
  display: block;
  width: 100%;
  height: 100%;
}

/* tb-ai-toggle-pinned */
.coop-page__head { flex-wrap: wrap; align-items: flex-start; }
.coop-page__head > * { min-width: 0; flex: 1 1 240px; }
.coop-page__head > .head__right { flex: none; width: auto; max-width: 100%; margin-left: auto; }
.coop-page__head { position: relative; padding-right: calc(16px + 48px); }
.coop-page__head :has([data-tb-ai-theme-toggle]) { position: static; }
.coop-page__head [data-tb-ai-theme-toggle] { position: absolute; top: 12px; right: 16px; margin: 0; z-index: 1; }

/* tb-ai-history-buttons */
button.tile__history.tile__history { border: 1px solid color-mix(in srgb, var(--tb-ai-primary, var(--tb-primary-500)) 28%, transparent); border-radius: 8px; background: color-mix(in srgb, var(--tb-ai-primary, var(--tb-primary-500)) 12%, transparent); color: var(--tb-ai-primary, var(--tb-primary-500)); cursor: pointer; box-shadow: 0 1px 2px rgba(0,0,0,0.18), inset 0 1px 0 color-mix(in srgb, var(--tb-ai-surface, #FFFFFF) 70%, transparent); transition: background 0.15s, box-shadow 0.15s; }
button.tile__history.tile__history:hover { background: color-mix(in srgb, var(--tb-ai-primary, var(--tb-primary-500)) 20%, transparent); box-shadow: 0 2px 5px rgba(0,0,0,0.22), inset 0 1px 0 color-mix(in srgb, var(--tb-ai-surface, #FFFFFF) 70%, transparent); }
button.tile__history.tile__history:active { box-shadow: inset 0 1px 3px rgba(0,0,0,0.25); }

/* tb-ai-fill */
.coop-page__view { flex: 1 0 auto; display: flex; flex-direction: column; }
.embed-wrapper { flex: 1 0 auto; height: auto; min-height: 480px; }

/* tb-ai-responsive */
@media (max-width: 959px) {
  .embed-wrapper:has(> tb-dashboard-state[stateid="coop-floor-plan"]) { height: 570px; min-height: 570px; }
  .embed-wrapper:has(> tb-dashboard-state[stateid="coop-controllers-overview"]) { height: 570px; min-height: 570px; }
  .embed-wrapper:has(> tb-dashboard-state[stateid="coop-alarms"]) { height: 570px; min-height: 570px; }
}

settings.js:
(function (key, fallbackDark) {
  var page = document.querySelector('.tb-dashboard-page');
  if (!page) { return; }
  var stored = null;
  try { stored = localStorage.getItem(key); } catch (e) {}
  page.classList.toggle('dark', stored ? stored === 'dark' : fallbackDark);
  page.setAttribute('data-tb-ai-theme-key', key);
  window.tbAiThemeOverlays = function () {
    var main = document.querySelector('.tb-dashboard-page');
    var themed = main && main.hasAttribute('data-tb-ai-theme-key');
    var dark = themed && main.classList.contains('dark');
    var styles = main ? getComputedStyle(main) : null;
    var surface = dark ? (styles.getPropertyValue('--tb-ai-surface').trim() || '#2A2C2F') : '';
    var muted = dark ? (styles.getPropertyValue('--tb-ai-text-secondary').trim() || '#94969C') : '';
    document.querySelectorAll('.cdk-overlay-container .tb-popover').forEach(function (popover) {
      var inner = popover.querySelector('.tb-dashboard-page');
      if (!inner || !themed) { return; }
      inner.classList.toggle('dark', dark);
      popover.querySelectorAll('.tb-popover-inner').forEach(function (el) {
        el.style.backgroundColor = surface;
        el.style.boxShadow = dark ? 'none' : '';
      });
      if (popover.parentElement) {
        var edge = 'rgba(255, 255, 255, 0.24)';
        popover.parentElement.style.filter = dark ? ['1px 0', '-1px 0', '0 1px', '0 -1px'].map(function (offset) {
          return 'drop-shadow(' + offset + ' 0 ' + edge + ')';
        }).join(' ') + ' drop-shadow(0 8px 24px rgba(255, 255, 255, 0.08))' : '';
      }
      popover.querySelectorAll('.tb-popover-arrow').forEach(function (arrow) {
        ['Top', 'Right', 'Bottom', 'Left'].forEach(function (side) {
          arrow.style['border' + side + 'Color'] = '';
          if (dark && getComputedStyle(arrow)['border' + side + 'Color'] !== 'rgba(0, 0, 0, 0)') {
            arrow.style['border' + side + 'Color'] = surface;
          }
        });
        arrow.style.boxShadow = dark ? 'none' : '';
      });
      popover.querySelectorAll('.tb-popover-close-button').forEach(function (el) { el.style.color = muted; });
    });
    var container = document.querySelector('.cdk-overlay-container');
    if (!container) { return; }
    var host = main && main.closest('tb-dashboard-page');
    var scope = host && Array.prototype.find.call(host.classList, function (name) {
      return name.indexOf('tb-dashboard-page-css-') === 0;
    });
    var canvas = dark ? (styles.getPropertyValue('--tb-ai-canvas').trim() || '#1E1F21') : '';
    var fullscreen = false;
    container.querySelectorAll('.tb-fullscreen-parent').forEach(function (pane) {
      if (!themed) { return; }
      pane.querySelectorAll('.tb-dashboard-page').forEach(function (page) { page.classList.toggle('dark', dark); });
      if (!scope || !pane.querySelector(':scope > .tb-widget') || !pane.parentElement) { return; }
      fullscreen = true;
      if (!pane.parentElement.classList.contains('tb-dashboard-page')) { pane.parentElement.classList.add('tb-dashboard-page'); }
      pane.parentElement.classList.toggle('dark', dark);
      if (!pane.classList.contains('tb-widget-container')) { pane.classList.add('tb-widget-container'); }
      if (!pane.hasAttribute('data-tb-ai-background')) { pane.setAttribute('data-tb-ai-background', pane.style.backgroundColor || ''); }
      pane.style.backgroundColor = dark ? canvas : pane.getAttribute('data-tb-ai-background');
    });
    var scoped = container.getAttribute('data-tb-ai-scope');
    if (scoped && (!fullscreen || scoped !== scope)) {
      container.classList.remove(scoped);
      container.removeAttribute('data-tb-ai-scope');
    }
    if (fullscreen && !container.classList.contains(scope)) {
      container.classList.add(scope);
      container.setAttribute('data-tb-ai-scope', scope);
    }
  };
  if (!window.tbAiThemeOverlayWatch) {
    window.tbAiThemeOverlayWatch = true;
    var watchOverlay = function () {
      var overlay = document.querySelector('.cdk-overlay-container');
      if (!overlay) { return false; }
      new MutationObserver(function () { window.tbAiThemeOverlays(); }).observe(overlay, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
      window.tbAiThemeOverlays();
      return true;
    };
    if (!watchOverlay()) {
      var bodyWatch = new MutationObserver(function () { if (watchOverlay()) { bodyWatch.disconnect(); } });
      bodyWatch.observe(document.body, { childList: true });
    }
  }
  window.tbAiThemeOverlays();
  if (window.tbAiThemeToggle) { return; }
  window.tbAiThemeToggle = function (event) {
