refreshTimer = setInterval(() => {
  if (this.lastUpdated) {
    this.freshnessText = ago(this.lastUpdated);
    ctx.detectChanges();
  }
}, 60000);

ctx.registerDestroyCallback(() => {
  if (subId) ctx.subscriptionApi.removeSubscription(subId);
  if (alarmSubId) ctx.subscriptionApi.removeSubscription(alarmSubId);
  if (refreshTimer) clearInterval(refreshTimer);
});
